#include <iostream>
#include <string>
using namespace std;

int main() {
    int N;
    cin >> N;
    cin.ignore();

    int balance = 0;
    bool valid = true;

    for (int i = 0; i < N; ++i) {
        string line;
        getline(cin, line);

        for (char c : line) {
            if (c == '{') {
                ++balance;
            } else if (c == '}') {
                --balance;
                if (balance < 0) valid = false;
            }
        }
    }

    cout << (valid && balance == 0 ? 'S' : 'N') << '\n';
    return 0;
}
